// Options configures one run.
type Options struct {
	Dir      string // any directory inside the repository
	Base     string // base ref; merge-base with HEAD is used
	Upstream string // branch new migrations must not collide with
	MigDir   string // optional migrations directory filter

	// These point Redline at something other than the working tree.
	// Each is materialized as a detached worktree, so the user's own
	// checkout is never moved.
	PR     string
	Branch string
	Commit string
	Range  string
	Out    string // evidence directory; excluded from the change like .redline/
}

// Result is a report plus the per-pane renders backing section 1 and the
// evidence artifacts findings point at.
type Result struct {
	Report   findings.Report
	Renders  []pane.Render
	Evidence map[string]pane.Artifact
	Target   *target.Target
	// Change is the file-by-file account of the diff the report renders its
	// walkthrough and drill-in sections from.
	Change *change.Set
	// LineCoverage overlays the profile onto the diff: per changed .go file,
	// each coverable line mapped to whether a test ran it. Nil when no profile.
	LineCoverage map[string]map[int]bool
}

// navLink is one sidebar entry.
//
// Count is shown when a section has a number worth knowing before you scroll to
// it. Warn marks a section that is a gap rather than a result — no captures of a
// UI that moved, no coverage profile, something undetermined — so the sidebar
// answers "what is missing here" without reading the page.
type navLink struct {
	ID    string
	Label string
	Count int
	Warn  bool
}

// Report is the merged result of one Redline run.
type Report struct {
	SchemaVersion int               `json:"schemaVersion"`
	BaseRef       string            `json:"baseRef"`
	BaseSHA       string            `json:"baseSHA,omitempty"`
	Scope         []string          `json:"scope,omitempty"`
	Findings      []Finding         `json:"findings"`
	Substrates    []SubstrateStatus `json:"substrates"`
	NewCount      map[Severity]int  `json:"newCount"`
	Coverage      Coverage          `json:"coverage"`

	Confirmations []Confirmation `json:"confirmations,omitempty"`
	Unknowns      []Unknown      `json:"unknowns,omitempty"`

	// Agent is the review narrative the agent wrote, read from review.json: an
	// overview of the change and a per-file summary, rendered as the agent's.
	Agent *AgentReview `json:"agent,omitempty"`
}

// Set is the change: the target, the commits, and every changed file.
type Set struct {
	Target  *target.Target `json:"target"`
	BaseSHA string         `json:"baseSHA"`

	Commits []gitx.Commit `json:"commits,omitempty"`
	Files   []File        `json:"files"`

	// UITouched is true when at least one changed file is classified as UI.
	// It decides how loud the absence of captures should be on the report: a
	// change that moves the interface with nothing captured is a gap, one that
	// touches no UI is not.
	UITouched bool `json:"uiTouched"`
}

func (r *repo) run(opts run.Options) *run.Result {
	r.t.Helper()
	opts.Dir = r.dir
	res, err := run.Run(opts)
	if err != nil {
		r.t.Fatalf("run: %v", err)
	}
	return res
}

// The skill that emits findings.json and the merge gate that reads it back
// depend on these exact field names; a rename here is a silent wire-format
// break neither side would compile-catch.
func TestReportJSONFieldNamesMatchTheWireContract(t *testing.T) {
	rep := findings.Report{
		Substrates:    []findings.SubstrateStatus{{Name: "s", State: findings.SubstrateRan}},
		Confirmations: []findings.Confirmation{{Substrate: "s", Rule: "r", Message: "ok"}},
		Unknowns:      []findings.Unknown{{Substrate: "s", Message: "could not tell"}},
		Coverage:      findings.Coverage{Diff: &cover.Result{Profile: "coverage.out", Lines: 10, Covered: 5, Percent: 50}},
	}
	rep.Finalize()
	b, err := json.Marshal(rep)
	if err != nil {
		t.Fatal(err)
	}
	body := string(b)
	for _, field := range []string{`"unknowns"`, `"confirmations"`, `"substrates"`, `"diffCoverage"`} {
		if !strings.Contains(body, field) {
			t.Errorf("Report JSON must carry field %s; the skill/merge gate reads it by name: %s", field, body)
		}
	}
}

// genReport builds a report with n findings spread over 20 files, four in
// five of them located on a changed line and the rest unlocated (riding in
// the body) — the shape BuildAttest actually walks on a large pull request.
func genReport(n int) *findings.Report {
	rep := &findings.Report{
		Coverage: findings.Coverage{ChangedFiles: 20, ExaminedFiles: 20},
		Substrates: []findings.SubstrateStatus{
			{Name: "migrations", State: findings.SubstrateRan},
			{Name: "openapi", State: findings.SubstrateSkipped, Detail: "no files in scope for this pane"},
			{Name: "lint", State: findings.SubstrateRan},
		},
	}
	for i := range n {
		f := findings.Finding{
			Rule:      fmt.Sprintf("rule-%d", i%12),
			Substrate: "migrations",
			Severity:  severityCycle[i%len(severityCycle)],
			Message:   fmt.Sprintf("finding %d: a realistic diagnostic message describing the issue in some detail", i),
		}
		if i%5 != 0 {
			f.File = fmt.Sprintf("internal/pkg%d/file%d.go", i%20, i%20)
			f.Line = (i % 50) + 1
		}
		rep.Findings = append(rep.Findings, f)
	}
	rep.Finalize()
	return rep
}

