// realisticReport builds a finalized report with findings spread across
// severities, categories, and the given files.
func realisticReport(nFindings int, files []change.File) *findings.Report {
	rules := []string{"migration-modified-after-merge", "endpoint-removed", "diff-coverage-below-threshold", "component-prop-removed"}
	cats := []findings.Category{findings.CategorySchema, findings.CategoryContract, findings.CategoryCover, findings.CategoryUI}
	fs := make([]findings.Finding, 0, nFindings)
	for i := range nFindings {
		fs = append(fs, findings.Finding{
			File:      files[i%len(files)].Path,
			Line:      i%40 + 1,
			Rule:      rules[i%len(rules)],
			Substrate: fmt.Sprintf("substrate-%d", i%5),
			Category:  cats[i%len(cats)],
			Message:   fmt.Sprintf("finding %d: behavior changed without a matching guard", i),
		})
	}
	rep := &findings.Report{
		BaseSHA:  "0123456789abcdef0123456789abcdef01234567",
		Findings: fs,
		Coverage: findings.Coverage{
			ChangedFiles:  len(files),
			ExaminedFiles: len(files),
			Diff:          &cover.Result{Profile: "coverage.out", Lines: 400, Covered: 300, Percent: 75},
		},
		Confirmations: []findings.Confirmation{{Substrate: "s", Rule: "r", Message: "no drift detected"}},
	}
	rep.Finalize()
	return rep
}

// The HTML report dropped pane.Render (the lint delta's "N introduced, M
// resolved", a suppression's added-directive list) on the floor entirely —
// markdown has rendered it since section1 existed. A report with a real
// lint delta and nothing under a "Lint" heading anywhere on the page is
// this bug; this is the regression test for it.
func TestWhatChangedSectionRendersPaneSummaries(t *testing.T) {
	html, err := HTML(HTMLInput{
		Report:  &findings.Report{Coverage: findings.Coverage{ChangedFiles: 1, ExaminedFiles: 1}},
		Change:  &change.Set{Files: []change.File{{Path: "a.go", Areas: []string{"code"}}}},
		Renders: []pane.Render{{Title: "Lint delta", Summary: "3 finding(s) introduced, 9 resolved (golangci-lint)"}},
	})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(html, `<h2 id="changed">What changed</h2>`) {
		t.Fatal("a change with pane renders must carry a What changed heading")
	}
	if !strings.Contains(html, "Lint delta") || !strings.Contains(html, "9 resolved") {
		t.Errorf("the pane's own render must appear on the page:\n%s", html)
	}
}

