	md := report.Markdown(&rep, nil, nil, nil)
	if strings.Contains(md, "redline/sql") || strings.Contains(md, "redline/api") {
		t.Errorf("the markdown report must not mention panes the repository has no files for:\n%s", md)
	}
}

